/// Process-wide live-write benchmark observations. Unlike the legacy TLS
/// reconstruction counter above, these atomics are incremented by the runtime
/// actor at the actual cache/load sites and may therefore be read by the test
/// driver without pretending its parent thread performed the work.
#[cfg(test)]
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, serde::Serialize)]
pub(crate) struct LiveWriteBenchmarkCounters {
    pub(crate) frontier_reconstructions: usize,
    pub(crate) document_head_reconstructions: usize,
    pub(crate) frontier_documents_requested: usize,
    pub(crate) archive_manifest_reads: usize,
    pub(crate) archive_object_reads: usize,
    pub(crate) baseline_state_loads: usize,
    pub(crate) visible_document_hits: usize,
    pub(crate) visible_document_misses: usize,
    pub(crate) hot_document_evictions: usize,
    pub(crate) cold_target_hits: usize,
    pub(crate) cold_target_misses: usize,
}

#[cfg(test)]
impl LiveWriteBenchmarkCounters {
    pub(crate) fn since(self, earlier: Self) -> Self {
        Self {
            frontier_reconstructions: self
                .frontier_reconstructions
                .saturating_sub(earlier.frontier_reconstructions),
            document_head_reconstructions: self
                .document_head_reconstructions
                .saturating_sub(earlier.document_head_reconstructions),
            frontier_documents_requested: self
                .frontier_documents_requested
                .saturating_sub(earlier.frontier_documents_requested),
            archive_manifest_reads: self
                .archive_manifest_reads
                .saturating_sub(earlier.archive_manifest_reads),
            archive_object_reads: self
                .archive_object_reads
                .saturating_sub(earlier.archive_object_reads),
            baseline_state_loads: self
                .baseline_state_loads
                .saturating_sub(earlier.baseline_state_loads),
            visible_document_hits: self
                .visible_document_hits
                .saturating_sub(earlier.visible_document_hits),
            visible_document_misses: self
                .visible_document_misses
                .saturating_sub(earlier.visible_document_misses),
            hot_document_evictions: self
                .hot_document_evictions
                .saturating_sub(earlier.hot_document_evictions),
            cold_target_hits: self
                .cold_target_hits
                .saturating_sub(earlier.cold_target_hits),
            cold_target_misses: self
                .cold_target_misses
                .saturating_sub(earlier.cold_target_misses),
        }
    }
}

