/// A concurrent same-block conflict pair, ordered by batch id so every
/// device derives the identical pair from the same two batches.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ConflictPair {
    pub min_batch: BatchId,
    pub min_author_device: DeviceId,
    pub max_batch: BatchId,
    pub max_author_device: DeviceId,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ConflictSiblingRetirement {
    pub block_id: BlockId,
    pub expected_content: String,
}

impl ConflictPair {
    fn from_manifests(left: &OperationBatch, right: &OperationBatch) -> Self {
        let (min, max) = if left.batch_id() <= right.batch_id() {
            (left, right)
        } else {
            (right, left)
        };
        Self {
            min_batch: min.batch_id(),
            min_author_device: min.author_device_id(),
            max_batch: max.batch_id(),
            max_author_device: max.author_device_id(),
        }
    }
}

/// Deterministic resolution work derived from an accepted batch that raced
/// concurrent history on the same block (GH #351, the git-like rule). The
/// intents are a pure function of the accepted batch set plus the merged
/// state, so every device that observes the completed pair derives the same
/// resolution; authoring is restricted to the pair's own author devices.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum ConflictResolutionIntent {
    /// edit-vs-delete: the tombstone won the owner-register race, but a
    /// concurrent edit proves the deletion removed state its author never
    /// saw. Re-assert the edited block; its text survives in the content
    /// container the tombstone never touched.
    RestoreEdited {
        page_id: PageId,
        block: BlockLocation,
        claim: MembershipClaim,
        source: super::BlockReconstructionSource,
        pair: ConflictPair,
    },
    /// move-vs-delete: the tombstone won the owner-register race against a
    /// concurrent move. Re-assert the move's destination ownership so the
    /// outcome is move-wins regardless of register luck.
    RestoreMoved {
        page_id: PageId,
        block: BlockLocation,
        claim: MembershipClaim,
        source: super::BlockReconstructionSource,
        pair: ConflictPair,
    },
    /// Overlapping same-block text edits: the CRDT merge is an interleave
    /// nobody typed. Keep both authored versions as adjacent sibling blocks,
    /// original block first in batch-id order.
    KeepBothTexts {
        page_id: PageId,
        block: BlockLocation,
        keep_text: String,
        sibling_text: String,
        merged_text: String,
        pair: ConflictPair,
    },
    /// Two concurrent observations represent one semantic edit, or a later
    /// operation on one branch reaches the other branch's exact authored
    /// state. Replace the unauthored CRDT interleave with that one converged
    /// text; creating a sibling here would turn a projection echo into data.
    ConvergeText {
        page_id: PageId,
        block: BlockLocation,
        content: String,
        retire_siblings: Vec<ConflictSiblingRetirement>,
        pair: ConflictPair,
    },
    /// A shared Markdown projection reached this device before the provider
    /// operation that produced it. The external-import lane therefore gave an
    /// unstamped new subtree fresh local identities, while the later provider
    /// batch carried the original identities for the same exact bytes. Retire
    /// only the externally observed duplicate roots; the ordinary local batch
    /// remains the one semantic creation.
    ConvergeProjectionCreate {
        page_id: PageId,
        retire_roots: Vec<BlockId>,
        resolution_author_device: DeviceId,
        pair: ConflictPair,
    },
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct ProjectionCreateShape {
    existing_parent: Option<BlockId>,
    order: String,
    content: String,
    children: Vec<ProjectionCreateShape>,
}

fn projection_effect_is_pure_create(effect: &SemanticEffect) -> bool {
    effect.pages().is_empty()
        && effect.page_preambles().is_empty()
        && !effect.blocks().is_empty()
        && effect.blocks().iter().all(|delta| {
            delta.before.is_none()
                && delta
                    .after
                    .as_ref()
                    .is_some_and(|after| matches!(after.owner, BlockOwner::Page(_)))
        })
        && effect.memberships().len() == effect.blocks().len()
        && effect
            .memberships()
            .iter()
            .all(|delta| delta.before.is_none() && delta.after.is_some())
}

fn projection_create_origins_match(x: BatchOrigin, z: BatchOrigin) -> bool {
    matches!(
        (x, z),
        (
            BatchOrigin::ExternalReconciliation { .. },
            BatchOrigin::LocalMutation
        ) | (
            BatchOrigin::LocalMutation,
            BatchOrigin::ExternalReconciliation { .. }
        )
    )
}

fn projection_create_forest(
    effect: &SemanticEffect,
    page_id: PageId,
) -> Option<(Vec<ProjectionCreateShape>, Vec<BlockId>)> {
    let created = effect
        .blocks()
        .iter()
        .filter_map(|delta| match (&delta.before, &delta.after) {
            (None, Some(after))
                if after.owner == BlockOwner::Page(page_id)
                    && after.logseq_uuid.is_none()
                    && after.logseq_identity_origin.is_none() =>
            {
                Some((delta.block_id, after))
            }
            _ => None,
        })
        .collect::<BTreeMap<_, _>>();
    if created.is_empty() {
        return None;
    }
    let memberships = created
        .keys()
        .map(|block_id| {
            let claim = effect
                .memberships()
                .iter()
                .find(|delta| {
                    delta.page_id == page_id
                        && delta.block_id == *block_id
                        && delta.before.is_none()
                })?
                .after
                .as_ref()?;
            Some((*block_id, claim))
        })
        .collect::<Option<BTreeMap<_, _>>>()?;
    if memberships.len() != created.len() {
        return None;
    }

    fn shape(
        block_id: BlockId,
        created: &BTreeMap<BlockId, &BlockState>,
        memberships: &BTreeMap<BlockId, &MembershipClaim>,
        visiting: &mut BTreeSet<BlockId>,
    ) -> Option<ProjectionCreateShape> {
        if !visiting.insert(block_id) {
            return None;
        }
        let block = created.get(&block_id)?;
        let claim = memberships.get(&block_id)?;
        let mut children = memberships
            .iter()
            .filter_map(|(candidate, candidate_claim)| {
                (candidate_claim.parent == Some(block_id)).then_some(*candidate)
            })
            .map(|child| shape(child, created, memberships, visiting))
            .collect::<Option<Vec<_>>>()?;
        visiting.remove(&block_id);
        children.sort_unstable();
        Some(ProjectionCreateShape {
            existing_parent: claim.parent.filter(|parent| !created.contains_key(parent)),
            order: claim.order.clone(),
            content: block.content.clone(),
            children,
        })
    }

    let mut roots = memberships
        .iter()
        .filter_map(|(block_id, claim)| {
            claim
                .parent
                .is_none_or(|parent| !created.contains_key(&parent))
                .then_some(*block_id)
        })
        .collect::<Vec<_>>();
    roots.sort_unstable();
    let mut forest = roots
        .iter()
        .map(|root| shape(*root, &created, &memberships, &mut BTreeSet::new()))
        .collect::<Option<Vec<_>>>()?;
    forest.sort_unstable();
    Some((forest, roots))
}

fn block_delta_edit_page(delta: &BlockDelta) -> Option<PageId> {
    match (&delta.before, &delta.after) {
        (Some(before), Some(after)) => match (before.owner, after.owner) {
            (BlockOwner::Page(page), BlockOwner::Page(same))
                if page == same && before.content != after.content =>
            {
                Some(page)
            }
            _ => None,
        },
        _ => None,
    }
}

fn block_delta_is_delete(delta: &BlockDelta) -> bool {
    matches!((&delta.before, &delta.after), (Some(before), None)
        if matches!(before.owner, BlockOwner::Page(_)))
}

fn block_delta_move_target(delta: &BlockDelta) -> Option<PageId> {
    match (&delta.before, &delta.after) {
        (Some(before), Some(after)) => match (before.owner, after.owner) {
            (BlockOwner::Page(source), BlockOwner::Page(target)) if source != target => {
                Some(target)
            }
            _ => None,
        },
        _ => None,
    }
}

fn membership_claim_in_effect(
    effect: &SemanticEffect,
    page_id: PageId,
    block_id: BlockId,
    after: bool,
) -> Option<MembershipClaim> {
    effect
        .memberships()
        .iter()
        .find(|delta| delta.page_id == page_id && delta.block_id == block_id)
        .and_then(|delta| {
            if after {
                delta.after.clone()
            } else {
                delta.before.clone()
            }
        })
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", deny_unknown_fields)]
pub enum SemanticOperation {
    CreatePage {
        page_id: PageId,
        home_document_id: DocumentId,
        name: LogicalPageName,
        path: ManagedPath,
        kind: ManagedTextKind,
    },
    EditPagePath {
        page_id: PageId,
        path: ManagedPath,
    },
    SetPageKind {
        page_id: PageId,
        kind: ManagedTextKind,
    },
    SetPagePreamble {
        page_id: PageId,
        preamble: Option<String>,
    },
    CreateBlock {
        block: BlockLocation,
        page_id: PageId,
        parent: Option<BlockId>,
        order: String,
        content: String,
    },
    EditBlockContent {
        block: BlockLocation,
        content: String,
    },
    MutateBlockLogseqIdentity {
        block: BlockLocation,
        mutation: LogseqIdentityMutation,
    },
    MoveSubtree {
        root: BlockLocation,
        from_page_id: PageId,
        to_page_id: PageId,
        parent: Option<BlockId>,
        order: String,
    },
    ReorderBlock {
        block_id: BlockId,
        page_id: PageId,
        parent: Option<BlockId>,
        order: String,
    },
    DeleteSubtree {
        root_block_id: BlockId,
        page_id: PageId,
    },
    DeletePage {
        page_id: PageId,
    },
    /// Restore one tombstoned catalog identity in place. The predecessor
    /// frontier is authenticated archive authority for the target snapshot;
    /// the intent id is best-effort layout provenance only.
    RevivePage {
        page_id: PageId,
        name: LogicalPageName,
        path: ManagedPath,
        kind: ManagedTextKind,
        deletion_batch_id: Option<BatchId>,
        predecessor_frontier: FrontierV2,
        prior_present_intent_id: Option<ProjectionIntentId>,
    },
    RenamePagesAndRewriteReferrers {
        page_changes: Vec<PageRename>,
        block_rewrites: Vec<BlockContentRewrite>,
        page_preamble_rewrites: Vec<PagePreambleRewrite>,
    },
    /// Deterministic conflict-resolution restore (GH #351): re-assert page
    /// reconstruct blocks whose visibility lost a race or whose accepted
    /// deletion is being undone. The explicit source selects accepted content
    /// and identity; every author inserts a new ordinary text container, and
    /// semantic conflict handling converges independently authored restores.
    RestoreSubtree {
        page_id: PageId,
        blocks: Vec<BlockRestore>,
    },
    ReconcileExternalPageState {
        page_id: PageId,
        name: LogicalPageName,
        path: ManagedPath,
        kind: ManagedTextKind,
    },
}

