#[derive(Clone, Debug, Eq, PartialEq)]
struct CapabilityCapturedPriorProjection {
    pub(crate) bytes: Vec<u8>,
    pub(crate) intent: ProjectionIntent,
    pub(crate) completion: Option<ProjectionCompletion>,
    pub(crate) bootstrap_owner_binding: Option<ContentDigest>,
    pub(crate) managed_local_authority: Option<(u64, BatchId)>,
    /// The exact latest source-endpoint work row reconstructed from accepted
    /// clean manifests. It is a run-local proof handle, not durable queue
    /// state; finalization re-derives and compares the current head.
    pub(crate) clean_manifest_authority: Option<ProjectionWork>,
}

/// Exact current graph-projection predecessor for the clean
/// baseline-plus-manifest runtime.  The value is reconstructed from immutable
/// authority on demand; it is deliberately not a second persistent path
/// index.  External reconciliation consumes it to preserve the established
/// page/block matching semantics without reopening `ProjectionWorkIndex`.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) enum CleanImportProjectionPredecessor {
    Present {
        page: MaterializedPage,
        bytes: Vec<u8>,
        intent: ProjectionIntent,
        completion: ProjectionCompletion,
        from_baseline: bool,
    },
    Released {
        prior_page_id: PageId,
        intent: ProjectionIntent,
        completion: ProjectionCompletion,
    },
}

/// Exact bytes expected at one clean-runtime projection path while deciding
/// whether an external observation needs semantic reconciliation.
///
/// This deliberately carries no mutation authority.  A changed path still
/// goes through `clean_import_projection_predecessor`, which performs the
/// complete semantic proof before authoring.  The watcher only needs a
/// no-false-negative byte comparison, so making every unchanged page replay
/// its parser and projection plan is both redundant and prohibitively slow.
pub(crate) enum CleanObservedProjection {
    Present(Vec<u8>),
    Released,
}

impl CapabilityCapturedPriorProjection {
    fn validate_authority(&self) -> Result<(), EngineError> {
        match (
            &self.completion,
            self.bootstrap_owner_binding,
            self.managed_local_authority,
            &self.clean_manifest_authority,
        ) {
            (Some(completion), None, None, None) => completion
                .validate_against(&self.intent)
                .map_err(|error| EngineError::ProjectionManifest(error.to_string())),
            (None, Some(_), None, None)
            | (None, None, Some(_), None)
            | (None, None, None, Some(_)) => Ok(()),
            _ => Err(EngineError::ProjectionManifest(
                "captured prior projection has ambiguous authority".into(),
            )),
        }
    }

    fn logical_completion_id(&self) -> Option<super::LogicalCompletionId> {
        self.completion
            .as_ref()
            .map(ProjectionCompletion::logical_completion_id)
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum CapabilityCapturedProjectionState {
    Absent,
    Present {
        bytes: Vec<u8>,
        prior_intent: ProjectionIntent,
        prior_completion: ProjectionCompletion,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum CapabilityCapturedProjectionMaterial {
    Absent {
        prior: Option<CapabilityCapturedPriorProjection>,
    },
    Present {
        bytes: Vec<u8>,
        annotations: Vec<AnnotatedIdentity>,
        prior: Option<CapabilityCapturedPriorProjection>,
    },
}

#[derive(Clone, Copy, Debug)]
enum MoveProjectionRenderLayout<'a> {
    DestinationObservation {
        base: &'a AnnotatedProjectionBase,
    },
    PriorSemanticProjection {
        reference: &'a ManifestObjectRef,
        base: &'a AnnotatedProjectionBase,
    },
}

impl<'a> MoveProjectionRenderLayout<'a> {
    fn manifest_render_base(self) -> Option<ManifestObjectRef> {
        match self {
            Self::DestinationObservation { .. } => None,
            Self::PriorSemanticProjection { reference, .. } => Some(reference.clone()),
        }
    }

    const fn base(self) -> &'a AnnotatedProjectionBase {
        match self {
            Self::DestinationObservation { base } | Self::PriorSemanticProjection { base, .. } => {
                base
            }
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CapabilityCapturedProjectionInput {
    path: ManagedPath,
    endpoint: ProjectionEndpointBinding,
    receipt_store_id: super::ProjectionReceiptStoreId,
    state: CapabilityCapturedProjectionState,
    material: CapabilityCapturedProjectionMaterial,
}

impl CapabilityCapturedProjectionInput {
    pub(crate) fn from_graph_capability(
        path: ManagedPath,
        endpoint: ProjectionEndpointBinding,
        receipt_store_id: super::ProjectionReceiptStoreId,
        state: CapabilityCapturedProjectionState,
    ) -> Self {
        let material = match &state {
            CapabilityCapturedProjectionState::Absent => {
                CapabilityCapturedProjectionMaterial::Absent { prior: None }
            }
            CapabilityCapturedProjectionState::Present {
                bytes,
                prior_intent,
                prior_completion,
            } => CapabilityCapturedProjectionMaterial::Present {
                bytes: bytes.clone(),
                annotations: prior_intent.annotations().to_vec(),
                prior: Some(CapabilityCapturedPriorProjection {
                    bytes: bytes.clone(),
                    intent: prior_intent.clone(),
                    completion: Some(prior_completion.clone()),
                    bootstrap_owner_binding: None,
                    managed_local_authority: None,
                    clean_manifest_authority: None,
                }),
            },
        };
        Self {
            path,
            endpoint,
            receipt_store_id,
            state,
            material,
        }
    }

    fn from_draft_capability(
        path: ManagedPath,
        endpoint: ProjectionEndpointBinding,
        receipt_store_id: super::ProjectionReceiptStoreId,
        material: CapabilityCapturedProjectionMaterial,
    ) -> Self {
        // Draft-only external capture can represent a newly present path or an
        // absent path with prior completion authority. That richer material is
        // deliberately private; the original public state enum remains source
        // compatible and is not used as the draft's authority.
        let state = match &material {
            CapabilityCapturedProjectionMaterial::Present {
                bytes,
                prior: Some(prior),
                ..
            } if prior.completion.is_some() => CapabilityCapturedProjectionState::Present {
                bytes: bytes.clone(),
                prior_intent: prior.intent.clone(),
                prior_completion: prior
                    .completion
                    .clone()
                    .expect("ordinary prior was selected by its completion"),
            },
            CapabilityCapturedProjectionMaterial::Present { prior: Some(_), .. }
            | CapabilityCapturedProjectionMaterial::Absent { .. }
            | CapabilityCapturedProjectionMaterial::Present { prior: None, .. } => {
                CapabilityCapturedProjectionState::Absent
            }
        };
        Self {
            path,
            endpoint,
            receipt_store_id,
            state,
            material,
        }
    }

    pub fn path(&self) -> &ManagedPath {
        &self.path
    }
}

