    #[test]
    fn block_claim_index_grows_past_any_fixed_capacity() {
        // Guard for the A4 fix: run-local identity indexes must never refuse
        // at a capacity (I-8: a refusal with no in-scope threat scenario is an
        // availability bug; I-10: the refusal was permanent across reopen).
        // See specs/campaigns/2026-09-invariant-sweep/A4-fix-dossier.md.
        let catalog = DocumentId::from_uuid(Uuid::from_u128(115_001));
        let mut engine = ShardedHotEngine::new(
            WorkspaceId::from_uuid(Uuid::from_u128(115_000)),
            LineageDigest::of(b"no-store-block-capacity"),
            catalog,
        );
        let retained_home = DocumentId::from_uuid(Uuid::from_u128(115_002));
        for key in 0..4_096usize {
            engine.ephemeral_block_claims.insert(
                key as u128,
                BTreeSet::from([ImmutableHomeClaim::new(
                    BatchId::from_uuid(Uuid::from_u128(115_003)),
                    retained_home,
                )]),
            );
        }
        let block_id = BlockId::from_uuid(Uuid::from_u128(115_010));
        let home = DocumentId::from_uuid(Uuid::from_u128(115_011));
        let birth_page_id = PageId::from_uuid(Uuid::from_u128(115_014));
        let effect = SemanticEffect::new(
            vec![PageDelta::ordinary(
                birth_page_id,
                None,
                Some(live_page(home, "pages/Birth.md")),
            )],
            vec![BlockDelta {
                block_id,
                home_document_id: home,
                birth: Some(BlockBirth {
                    page_id: birth_page_id,
                    page_document_id: home,
                }),
                reconstruction: None,
                before: None,
                after: Some(block_state(
                    block_id,
                    home,
                    BlockOwner::Tombstone,
                    "capacity candidate",
                )),
            }],
            Vec::new(),
        )
        .unwrap();
        let candidate = engine
            .validate_and_prepare_semantic_roles_and_block_homes(
                BatchId::from_uuid(Uuid::from_u128(115_012)),
                BatchCausalDot::new(
                    CausalPeerId::from_key(crate::oplog::WriterIncarnationId::fixture_for_device(
                        DeviceId::from_uuid(Uuid::from_u128(115_013)),
                    )),
                    1,
                )
                .unwrap(),
                &[],
                &effect,
                &BTreeMap::new(),
            )
            .expect(
                "a 4,097th lifetime block claim must validate: run-local identity \
                 indexes have no fixed capacity (I-8/I-10, A4-fix-dossier.md)",
            );
        assert!(
            candidate
                .ephemeral_block_claims
                .iter()
                .any(|(key, _)| *key == block_id.as_uuid().as_u128()),
            "the candidate must carry the new claim for insertion"
        );
    }

    #[test]
    fn pending_author_collision_never_exposes_the_wrong_speculative_state() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(100));
        let lineage = LineageDigest::of(b"pending-collision");
        let catalog = DocumentId::from_uuid(Uuid::from_u128(101));
        let page_a = PageId::from_uuid(Uuid::from_u128(102));
        let page_b = PageId::from_uuid(Uuid::from_u128(103));
        let home_a = DocumentId::from_uuid(Uuid::from_u128(104));
        let home_b = DocumentId::from_uuid(Uuid::from_u128(105));
        let author = test_author(106, 106);
        let mut engine = ShardedHotEngine::new(workspace, lineage, catalog);
        let original = engine
            .prepare_fixture_transaction(
                author,
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: page_a,
                    home_document_id: home_a,
                    name: crate::oplog::LogicalPageName::parse("A").unwrap(),
                    path: ManagedPath::parse("pages/A.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();
        let foreign_engine = ShardedHotEngine::new(workspace, lineage, catalog);
        let foreign = foreign_engine
            .prepare_fixture_transaction(
                author,
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: page_b,
                    home_document_id: home_b,
                    name: crate::oplog::LogicalPageName::parse("B").unwrap(),
                    path: ManagedPath::parse("pages/B.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();

        let before = engine.instrumentation();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(foreign))
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));
        let after = engine.instrumentation();
        assert_eq!(
            after.stage_structural_buffer_reuses - before.stage_structural_buffer_reuses,
            0
        );
        let snapshot = engine.canonical_snapshot().unwrap();
        assert!(!snapshot
            .pages
            .iter()
            .any(|(candidate, _)| *candidate == page_a));
        assert_eq!(
            snapshot
                .pages
                .iter()
                .find(|(candidate, _)| *candidate == page_b)
                .unwrap()
                .1
                .path(),
            Some(&ManagedPath::parse("pages/B.md").unwrap())
        );
        let before_collision = snapshot;
        assert!(matches!(
            engine.stage_ready(ValidatedBatch::new(original)).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::BatchCollision(found),
            } if found == author.batch_id
        ));
        assert_eq!(engine.canonical_snapshot().unwrap(), before_collision);
    }

