    #[test]
    fn mixed_new_and_existing_shards_do_not_skip_existing_declarations() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(91_500));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(91_501));
        let old_home = DocumentId::from_uuid(Uuid::from_u128(91_502));
        let old_page = PageId::from_uuid(Uuid::from_u128(91_503));
        let old_block = BlockId::from_uuid(Uuid::from_u128(91_504));
        let new_home = DocumentId::from_uuid(Uuid::from_u128(91_505));
        let new_page = PageId::from_uuid(Uuid::from_u128(91_506));
        let new_block = BlockId::from_uuid(Uuid::from_u128(91_507));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"mixed-fast-path"), catalog_id);
        let genesis = engine
            .prepare_fixture_transaction(
                test_author(91_510, 1),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id: old_page,
                        home_document_id: old_home,
                        name: crate::oplog::LogicalPageName::parse("Existing").unwrap(),
                        path: ManagedPath::parse("pages/Existing.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id: old_block,
                            home_document_id: old_home,
                        },
                        page_id: old_page,
                        parent: None,
                        order: "a".into(),
                        content: "original".into(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(genesis))
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let before_catalog = engine.clone_visible_document(catalog_id, 2).unwrap();
        let before_old = engine.clone_visible_document(old_home, 2).unwrap();
        let after_catalog = clone_doc(&before_catalog, 2).unwrap();
        insert_page_state(
            &after_catalog,
            new_page,
            &live_page(new_home, "pages/New.md"),
        )
        .unwrap();
        let after_old = clone_doc(&before_old, 2).unwrap();
        block_text(&after_old, old_block)
            .unwrap()
            .update("edited", UpdateOptions::default())
            .unwrap();
        let after_new = LoroDoc::new();
        after_new.set_peer_id(2).unwrap();
        after_new
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, new_page.to_string())
            .unwrap();
        after_new
            .get_map(SHARD_OWNERS)
            .insert(&new_block.to_string(), new_page.to_string())
            .unwrap();
        after_new
            .get_map(SHARD_CONTENT)
            .insert_container(&new_block.to_string(), LoroText::new())
            .unwrap()
            .insert(0, "new")
            .unwrap();
        insert_membership(
            &after_new,
            new_block,
            &MembershipClaim::new(new_home, None, "a").unwrap(),
        )
        .unwrap();
        let before = BTreeMap::from([
            (catalog_id, before_catalog),
            (old_home, before_old),
            (new_home, LoroDoc::new()),
        ]);
        let after = BTreeMap::from([
            (catalog_id, after_catalog),
            (old_home, after_old),
            (new_home, after_new),
        ]);
        let mut effect = derive_effect(catalog_id, &before, &after).unwrap();
        let mut blocks = effect.blocks().to_vec();
        blocks
            .iter_mut()
            .find(|delta| delta.home_document_id == old_home)
            .unwrap()
            .after
            .as_mut()
            .unwrap()
            .content = "incorrect existing declaration".into();
        effect = SemanticEffect::new(
            effect.pages().to_vec(),
            blocks,
            effect.memberships().to_vec(),
        )
        .unwrap();
        let frontier = FrontierV2::new(vec![
            dependencies_for(&engine, catalog_id, 2),
            dependencies_for(&engine, old_home, 2),
        ])
        .unwrap();
        let batch = validated_transition_with_effect(
            &engine,
            test_author(91_511, 2),
            &before,
            &after,
            frontier,
            effect,
        );
        assert!(matches!(
            engine.stage_ready(batch).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::SemanticEffectMismatch,
                ..
            }
        ));
        assert_eq!(
            engine.materialize_page(old_page).unwrap().blocks[0].content,
            "original"
        );
        assert!(matches!(
            engine.materialize_page(new_page),
            Err(EngineError::PageNotFound(_))
        ));
    }

    #[test]
    fn forged_initial_block_birth_page_and_home_reject_without_fragments() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(114_100));
        let catalog = DocumentId::from_uuid(Uuid::from_u128(114_101));
        let page_a = PageId::from_uuid(Uuid::from_u128(114_102));
        let page_b = PageId::from_uuid(Uuid::from_u128(114_103));
        let page_home_a = DocumentId::from_uuid(Uuid::from_u128(114_104));
        let page_home_b = DocumentId::from_uuid(Uuid::from_u128(114_105));
        let block_id = BlockId::from_uuid(Uuid::from_u128(114_106));
        let never_page = PageId::from_uuid(Uuid::from_u128(114_108));
        let never_home = DocumentId::from_uuid(Uuid::from_u128(114_109));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"forged-block-birth"), catalog);
        let pages = engine
            .prepare_fixture_transaction(
                test_author(114_110, 114_110),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id: page_a,
                        home_document_id: page_home_a,
                        name: LogicalPageName::parse("Birth A").unwrap(),
                        path: ManagedPath::parse("pages/birth-a.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreatePage {
                        page_id: page_b,
                        home_document_id: page_home_b,
                        name: LogicalPageName::parse("Birth B").unwrap(),
                        path: ManagedPath::parse("pages/birth-b.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine.stage_ready(ValidatedBatch::new(pages)).disposition(),
            BatchDisposition::Accepted { .. }
        ));

        // A block is born in one shard: its owner, text and membership land in
        // that document, and its birth is derived from the shard's immutable
        // page identity.
        let born_in = |shard: LoroDoc, home: DocumentId, owner_page: PageId| {
            shard
                .get_map(SHARD_OWNERS)
                .insert(&block_id.to_string(), owner_page.to_string())
                .unwrap();
            shard
                .get_map(SHARD_CONTENT)
                .insert_container(&block_id.to_string(), LoroText::new())
                .unwrap()
                .insert(0, "forged-birth-control")
                .unwrap();
            insert_membership(
                &shard,
                block_id,
                &MembershipClaim::new(home, None, "a").unwrap(),
            )
            .unwrap();
            shard
        };
        let legitimate = |engine: &ShardedHotEngine, peer: u64| {
            let before = engine.clone_visible_document(page_home_a, peer).unwrap();
            let after = born_in(clone_doc(&before, peer).unwrap(), page_home_a, page_a);
            let before = BTreeMap::from([(page_home_a, before)]);
            let after = BTreeMap::from([(page_home_a, after)]);
            let effect = derive_effect(catalog, &before, &after).unwrap();
            (before, after, effect)
        };

        let with_birth = |effect: &SemanticEffect, birth: BlockBirth| {
            let mut blocks = effect.blocks().to_vec();
            blocks[0].birth = Some(birth);
            SemanticEffect::new_with_page_preambles(
                effect.pages().to_vec(),
                effect.page_preambles().to_vec(),
                blocks,
                effect.memberships().to_vec(),
            )
            .unwrap()
        };
        let not_creation_shard = "block birth page document is not the block's creation shard";
        let lacks_live_identity =
            "block birth page/home lacks live identity at the declared causal base";

        // Changing only the shard's immutable page identity, from which birth
        // is derived, while retaining the legitimate declaration must fail at
        // the exact snapshot/effect comparison. This is the mismatch control,
        // distinct from birth authority below.
        let (before, after, legitimate_effect) = legitimate(&engine, 114_119);
        after[&page_home_a]
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, page_b.to_string())
            .unwrap();
        let batch = validated_transition_with_effect(
            &engine,
            test_author(114_119, 114_119),
            &before,
            &after,
            FrontierV2::new(vec![dependencies_for(&engine, page_home_a, 114_119)]).unwrap(),
            legitimate_effect,
        );
        let disposition = engine.stage_ready(batch).disposition().clone();
        assert!(
            matches!(
                &disposition,
                BatchDisposition::Rejected {
                    error: EngineError::MalformedDocument { document_id, reason },
                } if *document_id == page_home_a && reason == "stable shard page identity changed"
            ),
            "metadata-only birth forgery reached the wrong boundary: {disposition:?}"
        );
        assert!(engine.materialize_page(page_a).unwrap().blocks.is_empty());
        assert!(engine
            .recover_block_state(page_home_a, block_id)
            .unwrap()
            .is_none());

        // Retaining the legitimate CRDT change while declaring a birth that
        // disagrees with the creation shard is refused by birth authority: a
        // birth document other than the block's home fails the creation-shard
        // rule, and a wrong page at the right home fails the shard's causal
        // page identity. The stage-path comparator does not re-derive births
        // into an existing shard, so these two rules are the whole defence.
        for (index, (forged_birth, expected_reason)) in [
            (
                BlockBirth {
                    page_id: page_b,
                    page_document_id: page_home_b,
                },
                not_creation_shard,
            ),
            (
                BlockBirth {
                    page_id: page_a,
                    page_document_id: page_home_b,
                },
                not_creation_shard,
            ),
            (
                BlockBirth {
                    page_id: never_page,
                    page_document_id: never_home,
                },
                not_creation_shard,
            ),
            (
                BlockBirth {
                    page_id: page_b,
                    page_document_id: page_home_a,
                },
                lacks_live_identity,
            ),
        ]
        .into_iter()
        .enumerate()
        {
            let peer = 114_120 + index as u64;
            let (before, after, effect) = legitimate(&engine, peer);
            let batch = validated_transition_with_effect(
                &engine,
                test_author(114_120 + index as u128, peer),
                &before,
                &after,
                FrontierV2::new(vec![dependencies_for(&engine, page_home_a, peer)]).unwrap(),
                with_birth(&effect, forged_birth),
            );
            let disposition = engine.stage_ready(batch).disposition().clone();
            assert!(
                matches!(
                    &disposition,
                    BatchDisposition::Rejected {
                        error: EngineError::MalformedDocument { reason, .. },
                    } if reason == expected_reason
                ),
                "declared-birth forgery reached the wrong boundary: {disposition:?}"
            );
            assert!(engine.materialize_page(page_a).unwrap().blocks.is_empty());
            assert!(engine
                .recover_block_state(page_home_a, block_id)
                .unwrap()
                .is_none());
        }

        // A declared birth may not borrow a page born in the same batch whose
        // catalog home is an existing shard: that shard's immutable identity
        // is still page A.
        let alias_page = PageId::from_uuid(Uuid::from_u128(114_107));
        let peer = 114_125;
        let before_catalog = engine.clone_visible_document(catalog, peer).unwrap();
        let after_catalog = clone_doc(&before_catalog, peer).unwrap();
        insert_page_state(
            &after_catalog,
            alias_page,
            &live_page(page_home_a, "pages/birth-alias.md"),
        )
        .unwrap();
        let before_home = engine.clone_visible_document(page_home_a, peer).unwrap();
        let after_home = born_in(clone_doc(&before_home, peer).unwrap(), page_home_a, page_a);
        let before = BTreeMap::from([(catalog, before_catalog), (page_home_a, before_home)]);
        let after = BTreeMap::from([(catalog, after_catalog), (page_home_a, after_home)]);
        let effect = derive_effect(catalog, &before, &after).unwrap();
        let batch = validated_transition_with_effect(
            &engine,
            test_author(114_125, peer),
            &before,
            &after,
            FrontierV2::new(vec![
                dependencies_for(&engine, catalog, peer),
                dependencies_for(&engine, page_home_a, peer),
            ])
            .unwrap(),
            with_birth(
                &effect,
                BlockBirth {
                    page_id: alias_page,
                    page_document_id: page_home_a,
                },
            ),
        );
        let disposition = engine.stage_ready(batch).disposition().clone();
        assert!(
            matches!(
                &disposition,
                BatchDisposition::Rejected {
                    error: EngineError::MalformedDocument { document_id, reason },
                } if *document_id == page_home_a
                    && *reason == format!(
                        "catalog page {alias_page} does not match its immutable home shard identity"
                    )
            ),
            "same-batch page aliasing reached the wrong boundary: {disposition:?}"
        );
        assert!(engine.materialize_page(page_a).unwrap().blocks.is_empty());
        assert!(engine
            .recover_block_state(page_home_a, block_id)
            .unwrap()
            .is_none());
        assert!(matches!(
            engine.materialize_page(alias_page),
            Err(EngineError::PageNotFound(_))
        ));

        // Now make the shard AND the declared BlockBirth agree. A real page id,
        // or a never-created page, claimed by a shard that is not that page's
        // catalog home is an internally coherent CRDT/effect transition. Under
        // page shards the shard/catalog home binding refuses it before birth
        // authority is consulted; birth authority's causal rule is exercised
        // by the wrong-page case above. (A real page id at another real page's
        // shard cannot be coherent: that shard's page identity is immutable,
        // as `accepted_shard_page_identity_cannot_change` pins.)
        for (index, (forged_page, frontier, expected_reason)) in [
            (
                page_a,
                FrontierV2::new(vec![dependencies_for(&engine, page_home_a, 114_130)]).unwrap(),
                format!("shard identity {page_a} is not its catalog home"),
            ),
            (
                never_page,
                FrontierV2::new(Vec::new()).unwrap(),
                format!("shard identity references missing catalog page {never_page}"),
            ),
        ]
        .into_iter()
        .enumerate()
        {
            let peer = 114_130 + index as u64;
            let shard = LoroDoc::new();
            shard.set_peer_id(peer).unwrap();
            shard
                .get_map(SHARD_META)
                .insert(SHARD_PAGE_ID, forged_page.to_string())
                .unwrap();
            let before = BTreeMap::from([(never_home, LoroDoc::new())]);
            let after = BTreeMap::from([(never_home, born_in(shard, never_home, forged_page))]);
            let forged_effect = derive_effect(catalog, &before, &after).unwrap();
            assert_eq!(
                forged_effect.blocks()[0].birth,
                Some(BlockBirth {
                    page_id: forged_page,
                    page_document_id: never_home,
                })
            );
            let batch = validated_transition_with_effect(
                &engine,
                test_author(114_130 + index as u128, peer),
                &before,
                &after,
                frontier,
                forged_effect,
            );
            let disposition = engine.stage_ready(batch).disposition().clone();
            assert!(
                matches!(
                    &disposition,
                    BatchDisposition::Rejected {
                        error: EngineError::MalformedDocument { document_id, reason },
                    } if *document_id == never_home && *reason == expected_reason
                ),
                "coherent birth forgery reached the wrong boundary: {disposition:?}"
            );
            assert!(engine.materialize_page(page_a).unwrap().blocks.is_empty());
            assert!(!engine.visible_documents.contains_key(&never_home));
            assert!(matches!(
                engine.materialize_page(never_page),
                Err(EngineError::PageNotFound(_))
            ));
        }

        // A correct hand-built twin through the identical payload constructor
        // is accepted, ruling out malformed lane/frontier setup as the reason
        // the negative cases failed.
        let (before, after, legitimate_effect) = legitimate(&engine, 114_140);
        assert_eq!(
            legitimate_effect.blocks()[0].birth,
            Some(BlockBirth {
                page_id: page_a,
                page_document_id: page_home_a,
            })
        );
        let valid = validated_transition_with_effect(
            &engine,
            test_author(114_140, 114_140),
            &before,
            &after,
            FrontierV2::new(vec![dependencies_for(&engine, page_home_a, 114_140)]).unwrap(),
            legitimate_effect,
        );
        let valid_disposition = engine.stage_ready(valid).disposition().clone();
        assert!(
            matches!(valid_disposition, BatchDisposition::Accepted { .. }),
            "valid hand-built birth twin was not accepted: {valid_disposition:?}"
        );
        assert_eq!(engine.materialize_page(page_a).unwrap().blocks.len(), 1);
    }

    #[test]
    fn block_birth_identity_and_content_text_id_survive_delete_restore_and_replay() {
        use loro::ContainerTrait;

        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(114_200));
        let catalog = DocumentId::from_uuid(Uuid::from_u128(114_201));
        let page_id = PageId::from_uuid(Uuid::from_u128(114_202));
        let page_home = DocumentId::from_uuid(Uuid::from_u128(114_203));
        let block_id = BlockId::from_uuid(Uuid::from_u128(114_204));
        let mut engine = ShardedHotEngine::new(
            workspace,
            LineageDigest::of(b"stable-block-document-identity"),
            catalog,
        );
        // Only the creating batch declares where a block was born; a delete
        // or restore of it is a state change in that same creation shard.
        let declared_birth = |prepared: &PreparedBatch| {
            let semantic = prepared
                .objects()
                .iter()
                .find(|object| object.kind() == ObjectKind::SemanticEffect)
                .unwrap();
            SemanticEffect::decode(semantic.payload())
                .unwrap()
                .blocks()
                .iter()
                .find(|delta| delta.block_id == block_id)
                .map(|delta| delta.birth.clone())
                .expect("the batch changes the block")
        };
        let birth = engine
            .prepare_fixture_transaction(
                test_author(114_210, 114_210),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id,
                        home_document_id: page_home,
                        name: LogicalPageName::parse("Stable Block").unwrap(),
                        path: ManagedPath::parse("pages/stable-block.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id,
                            home_document_id: page_home,
                        },
                        page_id,
                        parent: None,
                        order: "a".into(),
                        content: "stable root text".into(),
                    },
                    SemanticOperation::MutateBlockLogseqIdentity {
                        block: BlockLocation {
                            block_id,
                            home_document_id: page_home,
                        },
                        mutation: LogseqIdentityMutation::AssignExternal {
                            logseq_uuid: LogseqUuid::from_uuid(Uuid::from_u128(114_205)),
                        },
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        assert_eq!(
            declared_birth(&birth),
            Some(BlockBirth {
                page_id,
                page_document_id: page_home,
            })
        );
        let birth = ValidatedBatch::new(birth);
        assert!(matches!(
            engine.stage_ready(birth.clone()).disposition(),
            BatchDisposition::Accepted { .. }
        ));
        let born = engine.clone_visible_document(page_home, 114_211).unwrap();
        assert_eq!(shard_page_id(&born).unwrap(), Some(page_id));
        let born_state = engine
            .recover_block_state(page_home, block_id)
            .unwrap()
            .unwrap();
        assert_eq!(born_state.owner, BlockOwner::Page(page_id));
        let born_text = block_text(&born, block_id).unwrap().id();

        let deletion = engine
            .prepare_fixture_transaction(
                test_author(114_212, 114_212),
                &OperationTransaction::new(vec![SemanticOperation::DeleteSubtree {
                    root_block_id: block_id,
                    page_id,
                }])
                .unwrap(),
            )
            .unwrap();
        assert_eq!(declared_birth(&deletion), None);
        let deletion = ValidatedBatch::new(deletion);
        assert!(matches!(
            engine.stage_ready(deletion.clone()).disposition(),
            BatchDisposition::Accepted { .. }
        ));
        let deleted = engine.clone_visible_document(page_home, 114_213).unwrap();
        assert_eq!(shard_page_id(&deleted).unwrap(), Some(page_id));
        assert_eq!(
            engine.recover_block_state(page_home, block_id).unwrap(),
            None
        );
        assert_eq!(
            engine
                .block_live_keys_for_test(page_home, block_id)
                .unwrap(),
            (false, false, false, false)
        );
        assert!(block_text(&deleted, block_id).is_none());

        let restoration = engine
            .prepare_fixture_transaction(
                test_author(114_214, 114_214),
                &OperationTransaction::new(vec![SemanticOperation::RestoreSubtree {
                    page_id,
                    blocks: vec![BlockRestore {
                        block: BlockLocation {
                            block_id,
                            home_document_id: page_home,
                        },
                        claim: MembershipClaim::new(page_home, None, "a").unwrap(),
                        source: crate::oplog::BlockReconstructionSource::DeletedBeforeImage {
                            deletion_batch_id: deletion.manifest().batch_id(),
                        },
                    }],
                }])
                .unwrap(),
            )
            .unwrap();
        assert_eq!(declared_birth(&restoration), None);
        let restoration = ValidatedBatch::new(restoration);
        assert!(matches!(
            engine.stage_ready(restoration.clone()).disposition(),
            BatchDisposition::Accepted { .. }
        ));
        let restored = engine.clone_visible_document(page_home, 114_215).unwrap();
        assert_eq!(shard_page_id(&restored).unwrap(), Some(page_id));
        assert_eq!(
            engine.recover_block_state(page_home, block_id).unwrap(),
            Some(born_state.clone())
        );
        let restored_text = block_text(&restored, block_id).unwrap().id();
        assert_ne!(restored_text, born_text);

        let mut replay = ShardedHotEngine::new(
            workspace,
            LineageDigest::of(b"stable-block-document-identity"),
            catalog,
        );
        for batch in [birth, deletion, restoration] {
            assert!(matches!(
                replay.stage_ready(batch).disposition(),
                BatchDisposition::Accepted { .. }
            ));
        }
        let replayed = replay.clone_visible_document(page_home, 114_216).unwrap();
        assert_eq!(shard_page_id(&replayed).unwrap(), Some(page_id));
        assert_eq!(
            replay.recover_block_state(page_home, block_id).unwrap(),
            Some(born_state)
        );
        assert_eq!(block_text(&replayed, block_id).unwrap().id(), restored_text);
    }

    #[test]
    fn crdt_witness_decode_rejects_duplicate_unsorted_and_noncanonical_heads() {
        let batch_id = BatchId::from_uuid(Uuid::from_u128(45));
        let document_id = DocumentId::from_uuid(Uuid::from_u128(46));
        let head_a = BatchId::from_uuid(Uuid::from_u128(47));
        let head_b = BatchId::from_uuid(Uuid::from_u128(48));
        for dependency_heads in [vec![head_a, head_a], vec![head_b, head_a]] {
            let bytes = postcard::to_allocvec(&CrdtUpdatePayload {
                schema_version: CRDT_UPDATE_PAYLOAD_SCHEMA_VERSION,
                batch_id,
                document_id,
                dependency_heads,
                batch_dependency_heads: vec![head_a],
                causal_state_digest: None,
                raw_update: vec![1],
            })
            .unwrap();
            assert!(matches!(
                decode_crdt_update_payload(batch_id, document_id, &bytes),
                Err(EngineError::InvalidCrdt(_))
            ));
        }

        let mut canonical = encode_crdt_update_payload(
            batch_id,
            document_id,
            vec![head_a],
            vec![head_a],
            None,
            vec![1],
        )
        .unwrap();
        canonical.push(0);
        assert!(matches!(
            decode_crdt_update_payload(batch_id, document_id, &canonical),
            Err(EngineError::InvalidCrdt(_))
        ));

        let future = postcard::to_allocvec(&CrdtUpdatePayload {
            schema_version: CRDT_UPDATE_PAYLOAD_SCHEMA_VERSION + 1,
            batch_id,
            document_id,
            dependency_heads: vec![head_a],
            batch_dependency_heads: vec![head_a],
            causal_state_digest: None,
            raw_update: vec![1],
        })
        .unwrap();
        assert!(matches!(
            decode_crdt_update_payload(batch_id, document_id, &future),
            Err(EngineError::InvalidCrdt(_))
        ));
    }

    #[test]
    fn malformed_and_referentially_incomplete_replacements_reject_atomically() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(1));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(2));
        let home_id = DocumentId::from_uuid(Uuid::from_u128(20));
        let page_id = PageId::from_uuid(Uuid::from_u128(10));
        let block_id = BlockId::from_uuid(Uuid::from_u128(30));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"lineage"), catalog_id);

        let catalog = LoroDoc::new();
        catalog.set_peer_id(50).unwrap();
        insert_page_state(
            &catalog,
            page_id,
            &PageState::Live {
                name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                path: ManagedPath::parse("pages/A.md").unwrap(),
                home_document_id: home_id,
                kind: ManagedTextKind::Page,
            },
        )
        .unwrap();
        let shard = LoroDoc::new();
        shard.set_peer_id(50).unwrap();
        shard
            .get_map(SHARD_OWNERS)
            .insert(&block_id.to_string(), page_id.to_string())
            .unwrap();
        shard
            .get_map(SHARD_CONTENT)
            .insert_container(&block_id.to_string(), LoroText::new())
            .unwrap()
            .insert(0, "coherent content without page identity")
            .unwrap();

        // A block's birth names its shard's page identity, so no author can
        // derive an effect for this shard. The most an author can honestly
        // declare is the catalog's page creation; the acceptor must still
        // refuse the unidentified shard that rides along with it.
        let declared = derive_effect(
            catalog_id,
            &BTreeMap::from([(catalog_id, LoroDoc::new())]),
            &BTreeMap::from([(catalog_id, catalog.clone())]),
        )
        .unwrap();
        let before = BTreeMap::from([(catalog_id, LoroDoc::new()), (home_id, LoroDoc::new())]);
        let after = BTreeMap::from([(catalog_id, catalog), (home_id, shard)]);
        let batch = validated_transition_with_effect(
            &engine,
            test_author(50, 50),
            &before,
            &after,
            FrontierV2::new(Vec::new()).unwrap(),
            declared,
        );
        assert!(matches!(
            engine.stage_ready(batch).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert!(engine.canonical_snapshot().unwrap().pages.is_empty());
        assert!(engine.visible_documents.is_empty());

        let catalog_only = LoroDoc::new();
        catalog_only.set_peer_id(51).unwrap();
        insert_page_state(
            &catalog_only,
            page_id,
            &PageState::Live {
                name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                path: ManagedPath::parse("pages/Catalog Only.md").unwrap(),
                home_document_id: home_id,
                kind: ManagedTextKind::Page,
            },
        )
        .unwrap();
        let catalog_only = validated_transition(
            &engine,
            test_author(51, 51),
            &BTreeMap::from([(catalog_id, LoroDoc::new())]),
            &BTreeMap::from([(catalog_id, catalog_only)]),
            FrontierV2::new(Vec::new()).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(catalog_only).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert!(engine.visible_documents.is_empty());

        let orphan_shard = LoroDoc::new();
        orphan_shard.set_peer_id(52).unwrap();
        orphan_shard
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, page_id.to_string())
            .unwrap();
        let orphan_shard = validated_transition(
            &engine,
            test_author(52, 52),
            &BTreeMap::from([(home_id, LoroDoc::new())]),
            &BTreeMap::from([(home_id, orphan_shard)]),
            FrontierV2::new(Vec::new()).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(orphan_shard).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert!(engine.visible_documents.is_empty());

        let missing_home_id = DocumentId::from_uuid(Uuid::from_u128(21));
        let referenced_block_id = BlockId::from_uuid(Uuid::from_u128(31));
        let catalog = LoroDoc::new();
        catalog.set_peer_id(53).unwrap();
        insert_page_state(
            &catalog,
            page_id,
            &PageState::Live {
                name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                path: ManagedPath::parse("pages/Missing Home.md").unwrap(),
                home_document_id: home_id,
                kind: ManagedTextKind::Page,
            },
        )
        .unwrap();
        let shard = LoroDoc::new();
        shard.set_peer_id(53).unwrap();
        shard
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, page_id.to_string())
            .unwrap();
        insert_membership(
            &shard,
            referenced_block_id,
            &MembershipClaim::new(missing_home_id, None, "a").unwrap(),
        )
        .unwrap();
        let missing_home = validated_transition(
            &engine,
            test_author(53, 53),
            &BTreeMap::from([(catalog_id, LoroDoc::new()), (home_id, LoroDoc::new())]),
            &BTreeMap::from([(catalog_id, catalog), (home_id, shard)]),
            FrontierV2::new(Vec::new()).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(missing_home).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert!(engine.visible_documents.is_empty());

        // None of the ordinary validation failures above may leave provisional
        // immutable-home evidence behind. The same identities remain valid for
        // a later coherent batch.
        let coherent = engine
            .prepare_fixture_transaction(
                test_author(54, 54),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id,
                        home_document_id: home_id,
                        name: crate::oplog::LogicalPageName::parse("Coherent").unwrap(),
                        path: ManagedPath::parse("pages/Coherent.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id,
                            home_document_id: home_id,
                        },
                        page_id,
                        parent: None,
                        order: "a".into(),
                        content: "accepted after ordinary rejections".into(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(coherent))
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));
        assert!(engine.fatal_evidence().is_none());
        assert_eq!(
            engine.materialize_page(page_id).unwrap().blocks[0].content,
            "accepted after ordinary rejections"
        );
    }

    #[test]
    fn raw_catalog_cannot_smuggle_shard_state_past_the_semantic_effect() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(61));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(62));
        let page_id = PageId::from_uuid(Uuid::from_u128(63));
        let block_id = BlockId::from_uuid(Uuid::from_u128(64));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"disjoint-roles"), catalog_id);

        let catalog = LoroDoc::new();
        catalog.set_peer_id(65).unwrap();
        insert_page_state(
            &catalog,
            page_id,
            &PageState::Live {
                name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                path: ManagedPath::parse("pages/Aliased.md").unwrap(),
                home_document_id: catalog_id,
                kind: ManagedTextKind::Page,
            },
        )
        .unwrap();
        catalog
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, page_id.to_string())
            .unwrap();
        catalog
            .get_map(SHARD_OWNERS)
            .insert(&block_id.to_string(), page_id.to_string())
            .unwrap();
        catalog
            .get_map(SHARD_CONTENT)
            .insert_container(&block_id.to_string(), LoroText::new())
            .unwrap()
            .insert(0, "semantically omitted content")
            .unwrap();
        insert_membership(
            &catalog,
            block_id,
            &MembershipClaim::new(catalog_id, None, "a").unwrap(),
        )
        .unwrap();

        let before = BTreeMap::from([(catalog_id, LoroDoc::new())]);
        let after = BTreeMap::from([(catalog_id, catalog)]);
        let declared_page_only_effect = SemanticEffect::new(
            vec![PageDelta {
                page_id,
                before: None,
                after: Some(PageState::Live {
                    name: crate::oplog::LogicalPageName::parse("Fixture Page").unwrap(),
                    path: ManagedPath::parse("pages/Aliased.md").unwrap(),
                    home_document_id: catalog_id,
                    kind: ManagedTextKind::Page,
                }),
                lifecycle: crate::oplog::PageDeltaLifecycle::Ordinary,
            }],
            Vec::new(),
            Vec::new(),
        )
        .unwrap();
        let batch = validated_transition_with_effect(
            &engine,
            test_author(65, 65),
            &before,
            &after,
            FrontierV2::new(Vec::new()).unwrap(),
            declared_page_only_effect,
        );
        let outcome = engine.stage_ready(batch);
        assert!(
            matches!(
                outcome.disposition(),
                BatchDisposition::Rejected {
                    error: EngineError::MalformedDocument { .. },
                    ..
                }
            ),
            "unexpected aliased-role outcome: {outcome:?}"
        );
        assert!(engine.canonical_snapshot().unwrap().pages.is_empty());
        assert!(engine.visible_documents.is_empty());
    }

    #[test]
    fn accepted_shard_page_identity_cannot_change() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(101));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(102));
        let home_id = DocumentId::from_uuid(Uuid::from_u128(120));
        let page_a = PageId::from_uuid(Uuid::from_u128(110));
        let page_b = PageId::from_uuid(Uuid::from_u128(111));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"identity"), catalog_id);
        let genesis = engine
            .prepare_fixture_transaction(
                test_author(200, 200),
                &OperationTransaction::new(vec![SemanticOperation::CreatePage {
                    page_id: page_a,
                    home_document_id: home_id,
                    name: crate::oplog::LogicalPageName::parse("A").unwrap(),
                    path: ManagedPath::parse("pages/A.md").unwrap(),
                    kind: ManagedTextKind::Page,
                }])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(genesis))
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let before_doc = engine.clone_visible_document(home_id, 201).unwrap();
        let changed = clone_doc(&before_doc, 201).unwrap();
        changed
            .get_map(SHARD_META)
            .insert(SHARD_PAGE_ID, page_b.to_string())
            .unwrap();
        let before = BTreeMap::from([(home_id, before_doc)]);
        let after = BTreeMap::from([(home_id, changed)]);
        let dependencies = DocumentDependencies::new(
            home_id,
            canonical_peer_counters(&before[&home_id].oplog_vv()).unwrap(),
            engine
                .document_dependency_heads(home_id, false)
                .unwrap()
                .into_iter()
                .collect(),
        )
        .unwrap();
        let batch = validated_transition_with_effect(
            &engine,
            test_author(201, 201),
            &before,
            &after,
            FrontierV2::new(vec![dependencies]).unwrap(),
            SemanticEffect::new(Vec::new(), Vec::new(), Vec::new()).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(batch).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::ShardPageIdentityChanged { .. }
                    | EngineError::MalformedDocument { .. },
                ..
            }
        ));
        assert_eq!(engine.materialize_page(page_a).unwrap().page_id, page_a);
    }

    #[test]
    fn proved_physical_removal_converges_and_unproved_removal_rejects_atomically() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(301));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(302));
        let home_id = DocumentId::from_uuid(Uuid::from_u128(320));
        let page_id = PageId::from_uuid(Uuid::from_u128(310));
        let block_id = BlockId::from_uuid(Uuid::from_u128(330));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"merged-residue"), catalog_id);
        let genesis = engine
            .prepare_fixture_transaction(
                test_author(400, 400),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id,
                        home_document_id: home_id,
                        name: crate::oplog::LogicalPageName::parse("Merge").unwrap(),
                        path: ManagedPath::parse("pages/Merge.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id,
                            home_document_id: home_id,
                        },
                        page_id,
                        parent: None,
                        order: "a".into(),
                        content: "baseline".into(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        let genesis = ValidatedBatch::new(genesis);
        assert!(matches!(
            engine.stage_ready(genesis.clone()).disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let dependencies = DocumentDependencies::new(
            home_id,
            canonical_peer_counters(
                &engine
                    .clone_visible_document(home_id, 401)
                    .unwrap()
                    .oplog_vv(),
            )
            .unwrap(),
            engine
                .document_dependency_heads(home_id, false)
                .unwrap()
                .into_iter()
                .collect(),
        )
        .unwrap();
        let frontier = FrontierV2::new(vec![dependencies]).unwrap();

        let removed_before = engine.clone_visible_document(home_id, 401).unwrap();
        let removed_after = clone_doc(&removed_before, 401).unwrap();
        removed_after
            .get_map(SHARD_OWNERS)
            .delete(&block_id.to_string())
            .unwrap();
        removed_after
            .get_map(SHARD_CONTENT)
            .delete(&block_id.to_string())
            .unwrap();
        removed_after
            .get_map(SHARD_MEMBERS)
            .delete(&block_id.to_string())
            .unwrap();
        let before_state = read_block_state(home_id, &removed_before, block_id)
            .unwrap()
            .unwrap();
        let removed_effect = raw_semantic_effect(
            Vec::new(),
            vec![BlockDelta {
                block_id,
                home_document_id: home_id,
                birth: None,
                reconstruction: None,
                before: Some(before_state),
                after: None,
            }],
            vec![MembershipDelta {
                page_id,
                block_id,
                before: Some(MembershipClaim::new(home_id, None, "a").unwrap()),
                after: None,
            }],
        );
        let removed = validated_transition_with_payload(
            &engine,
            test_author(401, 401),
            &BTreeMap::from([(home_id, removed_before)]),
            &BTreeMap::from([(home_id, removed_after)]),
            frontier.clone(),
            removed_effect,
        );

        let unproved_before = engine.clone_visible_document(home_id, 403).unwrap();
        let unproved_after = clone_doc(&unproved_before, 403).unwrap();
        unproved_after
            .get_map(SHARD_OWNERS)
            .delete(&block_id.to_string())
            .unwrap();
        unproved_after
            .get_map(SHARD_CONTENT)
            .delete(&block_id.to_string())
            .unwrap();
        let unproved_state = read_block_state(home_id, &unproved_before, block_id)
            .unwrap()
            .unwrap();
        let unproved = validated_transition_with_payload(
            &engine,
            test_author(403, 403),
            &BTreeMap::from([(home_id, unproved_before)]),
            &BTreeMap::from([(home_id, unproved_after)]),
            FrontierV2::new(vec![dependencies_for(&engine, home_id, 403)]).unwrap(),
            raw_semantic_effect(
                Vec::new(),
                vec![BlockDelta {
                    block_id,
                    home_document_id: home_id,
                    birth: None,
                    reconstruction: None,
                    before: Some(unproved_state),
                    after: None,
                }],
                Vec::new(),
            ),
        );

        let edited_before = engine.clone_visible_document(home_id, 402).unwrap();
        let edited_after = clone_doc(&edited_before, 402).unwrap();
        edited_after
            .get_map(SHARD_CONTENT)
            .delete(&block_id.to_string())
            .unwrap();
        edited_after
            .get_map(SHARD_CONTENT)
            .insert_container(&block_id.to_string(), LoroText::new())
            .unwrap()
            .insert(0, "concurrent replacement")
            .unwrap();
        let edited = validated_transition(
            &engine,
            test_author(402, 402),
            &BTreeMap::from([(home_id, edited_before)]),
            &BTreeMap::from([(home_id, edited_after)]),
            frontier,
        );

        let mut expected_snapshot = None;
        for removal_first in [true, false] {
            let mut receiver =
                ShardedHotEngine::new(workspace, LineageDigest::of(b"merged-residue"), catalog_id);
            assert!(matches!(
                receiver.stage_ready(genesis.clone()).disposition(),
                BatchDisposition::Accepted { .. }
            ));
            let ordered = if removal_first {
                [removed.clone(), edited.clone()]
            } else {
                [edited.clone(), removed.clone()]
            };
            for batch in ordered {
                let outcome = receiver.stage_ready(batch);
                assert!(
                    matches!(outcome.disposition(), BatchDisposition::Accepted { .. }),
                    "effect-proved removal or concurrent edit was refused: {outcome:?}"
                );
            }
            let snapshot = receiver.canonical_snapshot().unwrap();
            if let Some(expected) = &expected_snapshot {
                assert_eq!(&snapshot, expected);
            } else {
                expected_snapshot = Some(snapshot);
            }
        }

        for unproved_first in [true, false] {
            let mut receiver =
                ShardedHotEngine::new(workspace, LineageDigest::of(b"merged-residue"), catalog_id);
            assert!(matches!(
                receiver.stage_ready(genesis.clone()).disposition(),
                BatchDisposition::Accepted { .. }
            ));
            let before = receiver.canonical_snapshot().unwrap();
            let ordered = if unproved_first {
                [unproved.clone(), edited.clone()]
            } else {
                [edited.clone(), unproved.clone()]
            };
            let mut rejected = false;
            for batch in ordered {
                let is_unproved = batch.manifest().batch_id() == unproved.manifest().batch_id();
                let outcome = receiver.stage_ready(batch);
                if is_unproved {
                    assert!(
                        matches!(outcome.disposition(), BatchDisposition::Rejected { .. }),
                        "unproved removal with dangling membership was admitted: {outcome:?}"
                    );
                    rejected = true;
                } else {
                    assert!(matches!(
                        outcome.disposition(),
                        BatchDisposition::Accepted { .. }
                    ));
                }
            }
            assert!(rejected);
            let page = receiver.materialize_page(page_id).unwrap();
            assert_eq!(page.blocks.len(), 1);
            assert_eq!(page.blocks[0].content, "concurrent replacement");
            if unproved_first {
                assert_eq!(
                    before.blocks.len(),
                    1,
                    "rejection must preserve the live block"
                );
            }
        }

        let damaged = engine.visible_documents.get(&home_id).unwrap();
        damaged
            .get_map(SHARD_OWNERS)
            .delete(&block_id.to_string())
            .unwrap();
        damaged
            .get_map(SHARD_CONTENT)
            .delete(&block_id.to_string())
            .unwrap();
        assert!(matches!(
            engine.materialize_page(page_id),
            Err(EngineError::MalformedDocument { document_id, reason })
                if document_id == home_id && reason.contains("membership references missing block")
        ));
    }

    #[test]
    fn existing_block_id_cannot_be_duplicated_or_recreated_in_another_home() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(501));
        let catalog_id = DocumentId::from_uuid(Uuid::from_u128(502));
        let home_a = DocumentId::from_uuid(Uuid::from_u128(520));
        let home_b = DocumentId::from_uuid(Uuid::from_u128(521));
        let page_a = PageId::from_uuid(Uuid::from_u128(510));
        let page_b = PageId::from_uuid(Uuid::from_u128(511));
        let block_id = BlockId::from_uuid(Uuid::from_u128(530));
        let lineage = LineageDigest::of(b"immutable-block-home");
        let mut engine = ShardedHotEngine::new(workspace, lineage, catalog_id);
        let genesis = ValidatedBatch::new(
            engine
                .prepare_fixture_transaction(
                    test_author(600, 600),
                    &OperationTransaction::new(vec![
                        SemanticOperation::CreatePage {
                            page_id: page_a,
                            home_document_id: home_a,
                            name: crate::oplog::LogicalPageName::parse("A").unwrap(),
                            path: ManagedPath::parse("pages/A.md").unwrap(),
                            kind: ManagedTextKind::Page,
                        },
                        SemanticOperation::CreatePage {
                            page_id: page_b,
                            home_document_id: home_b,
                            name: crate::oplog::LogicalPageName::parse("B").unwrap(),
                            path: ManagedPath::parse("pages/B.md").unwrap(),
                            kind: ManagedTextKind::Page,
                        },
                        SemanticOperation::CreateBlock {
                            block: BlockLocation {
                                block_id,
                                home_document_id: home_a,
                            },
                            page_id: page_a,
                            parent: None,
                            order: "a".into(),
                            content: "immutable home A".into(),
                        },
                    ])
                    .unwrap(),
                )
                .unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(genesis.clone()).disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let duplicate_before = engine.clone_visible_document(home_b, 601).unwrap();
        let duplicate_after = clone_doc(&duplicate_before, 601).unwrap();
        duplicate_after
            .get_map(SHARD_OWNERS)
            .insert(&block_id.to_string(), page_b.to_string())
            .unwrap();
        duplicate_after
            .get_map(SHARD_CONTENT)
            .ensure_mergeable_text(&block_id.to_string())
            .unwrap()
            .insert(0, "duplicate home B")
            .unwrap();
        insert_membership(
            &duplicate_after,
            block_id,
            &MembershipClaim::new(home_b, None, "b").unwrap(),
        )
        .unwrap();
        let duplicate_author = test_author(601, 601);
        let duplicate = validated_transition(
            &engine,
            duplicate_author,
            &BTreeMap::from([(home_b, duplicate_before)]),
            &BTreeMap::from([(home_b, duplicate_after)]),
            FrontierV2::new(vec![dependencies_for(&engine, home_b, 601)]).unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(duplicate).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::BlockAlreadyExists(found),
                ..
            } if found == block_id
        ));
        assert_eq!(engine.fatal_evidence(), None);

        for (home_document_id, page_id) in [(home_a, page_a), (home_b, page_b)] {
            assert!(matches!(
                engine.prepare_fixture_transaction(
                    test_author(603, 603),
                    &OperationTransaction::new(vec![SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id,
                            home_document_id,
                        },
                        page_id,
                        parent: None,
                        order: "c".into(),
                        content: "author must consult global immutable-home evidence".into(),
                    }])
                    .unwrap(),
                ),
                Err(EngineError::BlockAlreadyExists(found)) if found == block_id
            ));
        }

        let same_batch_id = BlockId::from_uuid(Uuid::from_u128(531));
        let same_before_a = engine.clone_visible_document(home_a, 604).unwrap();
        let same_before_b = engine.clone_visible_document(home_b, 604).unwrap();
        let same_after_a = clone_doc(&same_before_a, 604).unwrap();
        let same_after_b = clone_doc(&same_before_b, 604).unwrap();
        for (document_id, page_id, document, order) in [
            (home_a, page_a, &same_after_a, "same-a"),
            (home_b, page_b, &same_after_b, "same-b"),
        ] {
            document
                .get_map(SHARD_OWNERS)
                .insert(&same_batch_id.to_string(), page_id.to_string())
                .unwrap();
            document
                .get_map(SHARD_CONTENT)
                .ensure_mergeable_text(&same_batch_id.to_string())
                .unwrap()
                .insert(0, order)
                .unwrap();
            insert_membership(
                document,
                same_batch_id,
                &MembershipClaim::new(document_id, None, order).unwrap(),
            )
            .unwrap();
        }
        let same_batch_duplicate = validated_transition(
            &engine,
            test_author(604, 604),
            &BTreeMap::from([(home_a, same_before_a), (home_b, same_before_b)]),
            &BTreeMap::from([(home_a, same_after_a), (home_b, same_after_b)]),
            FrontierV2::new(vec![
                dependencies_for(&engine, home_a, 604),
                dependencies_for(&engine, home_b, 604),
            ])
            .unwrap(),
        );
        assert!(matches!(
            engine.stage_ready(same_batch_duplicate).disposition(),
            BatchDisposition::Rejected {
                error: EngineError::BlockAlreadyExists(found),
            } if found == same_batch_id
        ));
        assert_eq!(engine.fatal_evidence(), None);
        assert!(engine
            .recover_block_state(home_a, same_batch_id)
            .unwrap()
            .is_none());
        assert!(engine
            .recover_block_state(home_b, same_batch_id)
            .unwrap()
            .is_none());
        let accepted_after_rollback = engine
            .prepare_fixture_transaction(
                test_author(605, 605),
                &OperationTransaction::new(vec![SemanticOperation::CreateBlock {
                    block: BlockLocation {
                        block_id: same_batch_id,
                        home_document_id: home_a,
                    },
                    page_id: page_a,
                    parent: None,
                    order: "accepted-after-rollback".into(),
                    content: "no provisional identity evidence remained".into(),
                }])
                .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            engine
                .stage_ready(ValidatedBatch::new(accepted_after_rollback))
                .disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let mut relocation_engine = ShardedHotEngine::new(workspace, lineage, catalog_id);
        assert!(matches!(
            relocation_engine.stage_ready(genesis).disposition(),
            BatchDisposition::Accepted { .. }
        ));

        let before_a = relocation_engine
            .clone_visible_document(home_a, 602)
            .unwrap();
        let before_b = relocation_engine
            .clone_visible_document(home_b, 602)
            .unwrap();
        let after_a = clone_doc(&before_a, 602).unwrap();
        after_a
            .get_map(SHARD_OWNERS)
            .delete(&block_id.to_string())
            .unwrap();
        after_a
            .get_map(SHARD_CONTENT)
            .delete(&block_id.to_string())
            .unwrap();
        after_a
            .get_map(SHARD_MEMBERS)
            .delete(&block_id.to_string())
            .unwrap();
        let after_b = clone_doc(&before_b, 602).unwrap();
        after_b
            .get_map(SHARD_OWNERS)
            .insert(&block_id.to_string(), page_b.to_string())
            .unwrap();
        after_b
            .get_map(SHARD_CONTENT)
            .ensure_mergeable_text(&block_id.to_string())
            .unwrap()
            .insert(0, "recreated home B")
            .unwrap();
        insert_membership(
            &after_b,
            block_id,
            &MembershipClaim::new(home_b, None, "b").unwrap(),
        )
        .unwrap();
        let removed_state = read_block_state(home_a, &before_a, block_id)
            .unwrap()
            .unwrap();
        let recreated_state = read_block_state(home_b, &after_b, block_id)
            .unwrap()
            .unwrap();
        let relocation_effect = raw_semantic_effect(
            Vec::new(),
            vec![
                BlockDelta {
                    block_id,
                    home_document_id: home_a,
                    birth: None,
                    reconstruction: None,
                    before: Some(removed_state),
                    after: None,
                },
                BlockDelta {
                    block_id,
                    home_document_id: home_b,
                    birth: Some(BlockBirth {
                        page_id: page_b,
                        page_document_id: home_b,
                    }),
                    reconstruction: None,
                    before: None,
                    after: Some(recreated_state),
                },
            ],
            vec![
                MembershipDelta {
                    page_id: page_a,
                    block_id,
                    before: Some(MembershipClaim::new(home_a, None, "a").unwrap()),
                    after: None,
                },
                MembershipDelta {
                    page_id: page_b,
                    block_id,
                    before: None,
                    after: Some(MembershipClaim::new(home_b, None, "b").unwrap()),
                },
            ],
        );
        let relocation = validated_transition_with_payload(
            &relocation_engine,
            test_author(602, 602),
            &BTreeMap::from([(home_a, before_a), (home_b, before_b)]),
            &BTreeMap::from([(home_a, after_a), (home_b, after_b)]),
            FrontierV2::new(vec![
                dependencies_for(&relocation_engine, home_a, 602),
                dependencies_for(&relocation_engine, home_b, 602),
            ])
            .unwrap(),
            relocation_effect,
        );
        let relocation_disposition = relocation_engine
            .stage_ready(relocation)
            .disposition()
            .clone();
        assert!(
            matches!(
                &relocation_disposition,
                BatchDisposition::Rejected {
                    error: EngineError::BlockAlreadyExists(found),
                    ..
                } if *found == block_id
            ),
            "relocation disposition: {relocation_disposition:?}"
        );
        assert_eq!(
            relocation_engine.materialize_page(page_a).unwrap().blocks[0].content,
            "immutable home A"
        );
        assert!(relocation_engine
            .materialize_page(page_b)
            .unwrap()
            .blocks
            .is_empty());
        assert!(relocation_engine
            .recover_block_state(home_b, block_id)
            .unwrap()
            .is_none());
    }

    #[test]
    fn compact_direct_parent_preserves_cross_document_atomic_ancestry() {
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(7_000));
        let catalog = DocumentId::from_uuid(Uuid::from_u128(7_001));
        let page_a = PageId::from_uuid(Uuid::from_u128(7_002));
        let page_b = PageId::from_uuid(Uuid::from_u128(7_003));
        let page_c = PageId::from_uuid(Uuid::from_u128(7_004));
        let home_a = DocumentId::from_uuid(Uuid::from_u128(7_005));
        let home_b = DocumentId::from_uuid(Uuid::from_u128(7_006));
        let home_c = DocumentId::from_uuid(Uuid::from_u128(7_007));
        let duplicate = BlockId::from_uuid(Uuid::from_u128(7_008));
        let support = BlockId::from_uuid(Uuid::from_u128(7_009));
        let mut engine =
            ShardedHotEngine::new(workspace, LineageDigest::of(b"cross-document"), catalog);
        let genesis = engine
            .prepare_fixture_transaction(
                test_author(7_010, 710),
                &OperationTransaction::new(vec![
                    SemanticOperation::CreatePage {
                        page_id: page_a,
                        home_document_id: home_a,
                        name: crate::oplog::LogicalPageName::parse("A").unwrap(),
                        path: ManagedPath::parse("pages/A.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreatePage {
                        page_id: page_b,
                        home_document_id: home_b,
                        name: crate::oplog::LogicalPageName::parse("B").unwrap(),
                        path: ManagedPath::parse("pages/B.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                    SemanticOperation::CreatePage {
                        page_id: page_c,
                        home_document_id: home_c,
                        name: crate::oplog::LogicalPageName::parse("C").unwrap(),
                        path: ManagedPath::parse("pages/C.md").unwrap(),
                        kind: ManagedTextKind::Page,
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        engine.stage_ready(ValidatedBatch::new(genesis));
        let ancestor = engine
            .prepare_fixture_transaction(
                test_author(7_011, 711),
                &OperationTransaction::new(vec![SemanticOperation::CreateBlock {
                    block: BlockLocation {
                        block_id: duplicate,
                        home_document_id: home_a,
                    },
                    page_id: page_a,
                    parent: None,
                    order: "a".into(),
                    content: "ancestor identity".into(),
                }])
                .unwrap(),
            )
            .unwrap();
        engine.stage_ready(ValidatedBatch::new(ancestor));
        let atomic_parent = engine
            .prepare_fixture_transaction(
                test_author(7_012, 712),
                &OperationTransaction::new(vec![
                    SemanticOperation::EditBlockContent {
                        block: BlockLocation {
                            block_id: duplicate,
                            home_document_id: home_a,
                        },
                        content: "parent touched ancestor document".into(),
                    },
                    SemanticOperation::CreateBlock {
                        block: BlockLocation {
                            block_id: support,
                            home_document_id: home_b,
                        },
                        page_id: page_b,
                        parent: None,
                        order: "support".into(),
                        content: "parent also touched child document".into(),
                    },
                ])
                .unwrap(),
            )
            .unwrap();
        engine.stage_ready(ValidatedBatch::new(atomic_parent));

        let authored_descendant = engine
            .prepare_fixture_transaction(
                test_author(7_014, 714),
                &OperationTransaction::new(vec![SemanticOperation::EditBlockContent {
                    block: BlockLocation {
                        block_id: support,
                        home_document_id: home_b,
                    },
                    content: "legitimate cross-document descendant".into(),
                }])
                .unwrap(),
            )
            .unwrap();
        assert!(authored_descendant
            .manifest()
            .dependency_frontier()
            .documents()
            .iter()
            .any(|entry| {
                entry.document_id() == home_b
                    && entry.direct_dependency_heads()
                        == [BatchId::from_uuid(Uuid::from_u128(7_012))]
            }));
        assert!(!authored_descendant
            .manifest()
            .dependency_frontier()
            .documents()
            .iter()
            .any(|entry| entry.document_id() == home_a));

        let before_c = engine.clone_visible_document(home_c, 713).unwrap();
        let after_c = clone_doc(&before_c, 713).unwrap();
        after_c
            .get_map(SHARD_OWNERS)
            .insert(&duplicate.to_string(), page_c.to_string())
            .unwrap();
        after_c
            .get_map(SHARD_CONTENT)
            .ensure_mergeable_text(&duplicate.to_string())
            .unwrap()
            .insert(0, "omitted cross-document ancestor")
            .unwrap();
        insert_membership(
            &after_c,
            duplicate,
            &MembershipClaim::new(home_c, None, "duplicate").unwrap(),
        )
        .unwrap();
        let malformed = validated_transition(
            &engine,
            test_author(7_013, 713),
            &BTreeMap::from([(home_c, before_c)]),
            &BTreeMap::from([(home_c, after_c)]),
            FrontierV2::new(vec![
                dependencies_for(&engine, home_b, 713),
                dependencies_for(&engine, home_c, 713),
            ])
            .unwrap(),
        );
        let malformed_outcome = engine.stage_ready(malformed).disposition();
        assert!(
            matches!(
                malformed_outcome,
                BatchDisposition::Rejected {
                    error: EngineError::BlockAlreadyExists(found),
                }
                if found == duplicate
            ),
            "unexpected malformed ancestry outcome: {malformed_outcome:?}"
        );
        assert_eq!(engine.fatal_evidence(), None);
    }

